SELECT": "m.merchantBusinessName, dr.deviceId, SUM(dr.totalTransactionsPlayed) AS highValueTransactions",
    "FROM": "merchantInfo m",
    "INNER JOIN": [
        {
            "relation": "merchantRelationInfo mr",
            "condition": "m.merchantId = mr.merchantId"
        },
        {
            "relation": "deviceRelationInfo dr",
            "condition": "mr.relationId = dr.relationId"
        }
    ],
    "WHERE": [
        {
            "column": "dr.totalTransactionsPlayed",
            "operator": "> 80000",
            "condition": "dr.totalTransactionsPlayed > 80000"
        }
    ],
    "GROUP BY": [
        "m.merchantBusinessName",
        "dr.deviceId"
    ],
    "LIMIT": 50
}
